// Generates public/media/day-NN/narration.png and resolution.png with the ElevenLabs Image API
// (POST /v1/flows/image), from the image prompts in content/texts.md.
//
//   npm run images                       all missing or changed images
//   npm run images -- --dry-run          only list what would be generated
//   npm run images -- --day 3            one day (also: --day 3-7)
//   npm run images -- --only narration   narration or resolution only
//   npm run images -- --force            also overwrite images that were not generated by this script
//   npm run images -- --parallel 4       generations at the same time (default 2)
//
// Needs ELEVENLABS_API_KEY in .env (the same key as for npm run tts; it needs the Image & Video permission
// and a Pro plan or above). Optional: ELEVENLABS_IMAGE_MODEL.
// Model, options, style prompt and style reference images: content/image-settings.json.
// content/image-manifest.json remembers a hash of everything behind each image, so re-running only
// regenerates what changed. An image that gets replaced is first copied to media-backup/day-NN/ (with a
// timestamp, gitignored), so old versions are never lost. Days with a video resolution (solutions.json "video") only get the narration image.
import { copyFileSync, existsSync, mkdirSync, readFileSync, renameSync, writeFileSync } from 'node:fs';
import { createHash } from 'node:crypto';
import { extname } from 'node:path';
import { parseTexts } from './parse-texts.mjs';

const args = process.argv.slice(2);
const flag = (name) => args.includes(`--${name}`);
const opt = (name) => { const i = args.indexOf(`--${name}`); return i >= 0 ? args[i + 1] : undefined; };

const dryRun = flag('dry-run');
const force = flag('force');
const only = opt('only');
if (only && !['narration', 'resolution'].includes(only)) throw new Error('--only must be narration or resolution');
const [from, to] = (opt('day') ?? '1-24').split('-').map(Number);
const dayRange = [from, to ?? from];
const parallel = Math.max(1, Number(opt('parallel') ?? 2));

const API_KEY = process.env.ELEVENLABS_API_KEY;
const API = 'https://api.elevenlabs.io';
const settings = JSON.parse(readFileSync(new URL('../content/image-settings.json', import.meta.url), 'utf8'));
const MODEL = process.env.ELEVENLABS_IMAGE_MODEL || settings.model;
const STYLE = (settings.stylePrompt ?? '').trim();
const EXTS = ['webp', 'jpg', 'png']; // the app tries them in this order
const MIME_EXT = { 'image/png': 'png', 'image/jpeg': 'jpg', 'image/webp': 'webp' };

if (!dryRun && !API_KEY) {
  console.error('Set ELEVENLABS_API_KEY in .env (see README, "Images with ElevenLabs").');
  process.exit(1);
}

// Style references: local images sent along with every prompt (field "images", max 10) to anchor the look.
const MIME_BY_EXT = { '.png': 'image/png', '.jpg': 'image/jpeg', '.jpeg': 'image/jpeg', '.webp': 'image/webp' };
const references = (settings.styleReferences ?? []).map((p) => {
  const data = readFileSync(new URL(`../${p}`, import.meta.url));
  const mime = MIME_BY_EXT[extname(p).toLowerCase()];
  if (!mime) throw new Error(`Style reference ${p}: use png, jpg or webp`);
  return { digest: createHash('sha256').update(data).digest('hex').slice(0, 12), ref: { type: 'inline_base64', content_base64: data.toString('base64'), mime_type: mime } };
});

// The API rejects fields a model does not support, so only send what the model takes.
function requestBody(prompt) {
  const body = { model_id: MODEL, prompt, ...settings.options };
  if (settings.seed != null && MODEL.startsWith('bytedance-seedream')) body.seed = settings.seed;
  if (references.length) body.images = references.map((r) => r.ref);
  return body;
}

const manifestUrl = new URL('../content/image-manifest.json', import.meta.url);
const manifest = existsSync(manifestUrl) ? JSON.parse(readFileSync(manifestUrl, 'utf8')) : {};
const saveManifest = () => writeFileSync(manifestUrl, JSON.stringify(manifest, null, 2) + '\n');

const solutions = JSON.parse(readFileSync(new URL('../content/solutions.json', import.meta.url), 'utf8')).days;
const days = parseTexts();
const mediaDir = (num) => new URL(`../public/media/day-${String(num).padStart(2, '0')}/`, import.meta.url);

const jobs = [];
for (let num = dayRange[0]; num <= dayRange[1]; num++) {
  const d = days[num];
  if (!d) throw new Error(`Day ${num} missing in texts.md`);
  if ((settings.skipDays ?? []).includes(num)) { console.log(`Day ${num}: listed in skipDays, skipped`); continue; }
  for (const kind of ['narration', 'resolution']) {
    if (only && kind !== only) continue;
    const scene = (kind === 'narration' ? d.imageNarration : d.imageResolution).trim();
    if (!scene) { console.warn(`Day ${num}: no ${kind} image prompt, skipped`); continue; }
    if (kind === 'resolution' && solutions[String(num)]?.video) { console.log(`Day ${num}: resolution is a video, skipped`); continue; }
    const prompt = STYLE ? `${scene}\n\nStyle: ${STYLE}` : scene;
    const key = `day-${String(num).padStart(2, '0')}/${kind}`;
    const body = requestBody(prompt);
    const hash = createHash('sha256').update(JSON.stringify([{ ...body, images: references.map((r) => r.digest) }])).digest('hex').slice(0, 16);
    const existing = EXTS.filter((e) => existsSync(new URL(`${kind}.${e}`, mediaDir(num))));
    const entry = manifest[key];
    if (existing.length) {
      if (entry?.hash === hash) continue; // up to date
      if (!entry && !force) { console.log(`${key}.${existing[0]} exists and was not generated here, kept (use --force to replace)`); continue; }
    }
    jobs.push({ key, num, kind, prompt, body, hash });
  }
}

console.log(`Model ${MODEL}, options ${JSON.stringify(settings.options)}, ${references.length} style reference(s)`);
console.log(`${jobs.length} image(s)`);
if (dryRun) { for (const j of jobs) console.log(`  ${j.key}  ${j.prompt.slice(0, 90).replace(/\n/g, ' ')}…`); process.exit(0); }

const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
const headers = { 'xi-api-key': API_KEY, 'Content-Type': 'application/json' };

// fetch with retries on rate limits and server errors
async function call(url, init, label) {
  for (let attempt = 1; ; attempt++) {
    const res = await fetch(url, init);
    if (res.ok) return res;
    const text = await res.text();
    if ((res.status === 429 || res.status >= 500) && attempt < 5) {
      const wait = 2 ** attempt * 1000;
      console.warn(`  ${label}: ${res.status}, retrying in ${wait / 1000}s`);
      await sleep(wait);
      continue;
    }
    throw new Error(`${label}: ElevenLabs ${res.status}: ${text}`);
  }
}

async function generate(job) {
  const created = await (await call(`${API}/v1/flows/image`, { method: 'POST', headers, body: JSON.stringify(job.body) }, job.key)).json();
  const deadline = Date.now() + 10 * 60 * 1000;
  for (;;) {
    await sleep(3000); // the docs ask for no more than one request every 2 seconds
    const r = await (await call(`${API}/v1/flows/image/${created.id}`, { headers: { 'xi-api-key': API_KEY } }, job.key)).json();
    if (r.status === 'completed') {
      const img = await call(r.content_url, {}, job.key); // signed URL, no auth header
      return { data: Buffer.from(await img.arrayBuffer()), mime: r.content_mime_type, id: created.id };
    }
    if (r.status === 'failed') throw new Error(`${job.key}: ${r.failure_reason}: ${r.error_message}`);
    if (Date.now() > deadline) throw new Error(`${job.key}: timed out`);
  }
}

const failures = [];
const queue = [...jobs];
async function worker() {
  for (let job = queue.shift(); job; job = queue.shift()) {
    try {
      const { data, mime, id } = await generate(job);
      const ext = MIME_EXT[mime] ?? 'png';
      const dir = mediaDir(job.num);
      mkdirSync(dir, { recursive: true });
      const file = new URL(`${job.kind}.${ext}`, dir);
      if (existsSync(file)) {
        // Keep the old picture: media-backup/day-NN/narration.2026-11-08T11-30-00.png
        const backupDir = new URL(`../media-backup/day-${String(job.num).padStart(2, '0')}/`, import.meta.url);
        mkdirSync(backupDir, { recursive: true });
        const stamp = new Date().toISOString().replace(/\.\d+Z$/, '').replace(/:/g, '-');
        copyFileSync(file, new URL(`${job.kind}.${stamp}.${ext}`, backupDir));
      }
      const tmp = new URL(`${file.href}.tmp`);
      writeFileSync(tmp, data);
      renameSync(tmp, file);
      manifest[job.key] = { hash: job.hash, model: MODEL, options: settings.options, file: `${job.kind}.${ext}`, generation: id, prompt: job.prompt, generated: new Date().toISOString() };
      saveManifest(); // after every image, so an interrupted run resumes where it stopped
      const shadow = EXTS.filter((e) => e !== ext && existsSync(new URL(`${job.kind}.${e}`, dir)) && EXTS.indexOf(e) < EXTS.indexOf(ext));
      console.log(`${job.key}.${ext}  ${(data.length / 1024).toFixed(0)} KB${shadow.length ? `  ⚠ ${job.kind}.${shadow.join('/')} also exists and is shown first by the app` : ''}`);
    } catch (e) {
      failures.push(job.key);
      console.error(`✗ ${e.message}`);
    }
  }
}
await Promise.all(Array.from({ length: Math.min(parallel, jobs.length) }, worker));
if (failures.length) { console.error(`${failures.length} failed: ${failures.join(', ')} (run again to retry them)`); process.exit(1); }
console.log('Done.');
